  "claims": [
    {
      "claim": "The closest measured morphinan analog in the visible records, samidorphan, has an absolute oral bioavailability of about 69% (mean 68.6%, range 60.3–82.6%) after a single 2 mg oral dose in healthy volunteers, well above the 20% threshold; the query is an oxycodone-type 4,5-epoxymorphinan-6-one in the same opioid scaffold family.",
      "card_ids": ["C01", "C02", "C06", "C17"]
    },
    {
      "claim": "L2 records describe samidorphan as having much greater or increased oral bioavailability compared with naltrexone, consistent with the quantitative F value and supporting transfer of high-F evidence to the morphinan scaffold.",
      "card_ids": ["C22", "C27"]
    },
    {
      "claim": "L5 gut-wall/intestinal permeability records for related morphinans show high Caco-2/MDCK permeability and rapid small-intestinal absorption, with no evidence of an efflux-limited barrier for this scaffold.",
      "card_ids": ["C54", "C56", "C57", "C60"]
    },
    {
      "claim": "L6 hepatic-clearance/metabolic-stability records are for related opioids/morphinans in microsomal, recombinant, or animal systems; they show mixed intrinsic clearance and do not provide query-specific or human oral-bioavailability evidence, so they do not affirmatively support F < 20%.",
      "card_ids": ["C66", "C67", "C68", "C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76", "C77"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C66", "C67", "C68", "C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76", "C77"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself is present in the visible records; the decision relies on a structurally related morphinan (samidorphan), related morphinan permeability records, and the physicochemical prior.",
    "Samidorphan differs from the query in N-substituent and aromatic substituents, and morphine/codeine differ at C6 and C7-C8; transfer is not exact.",
    "No query-specific gut-wall efflux, intestinal metabolism, hepatic clearance, or metabolic-stability data are available; L5/L6 records are for related or unrelated molecules.",
    "No formulation-specific, dose-ranging, or condition-matched data for the query are available in the visible records."
  ],
  "decision_summary": "Keep high (F >= 20%): the query is an oxycodone-type 4,5-epoxymorphinan-6-one with a favorable physicochemical prior; the closest measured morphinan analog samidorphan has absolute oral bioavailability ~69%, and L5 gut-wall/intestinal permeability records for related morphinans show high permeability and rapid intestinal absorption with no efflux-limited barrier. L6 hepatic-clearance/metabolic-stability records are for related molecules in non-query systems, show mixed intrinsic clearance, and do not provide affirmative evidence for F < 20%; confidence remains moderate because no direct query F measurement is present."
}

